int main(int argc,char**argv){if(argc<2)return 2; FILE*f=fopen(argv[1],"rb"); if(!f){perror("fopen");return 2;} fseek(f,0,SEEK_END); long n=ftell(f); rewind(f); unsigned char*buf=malloc(n); fread(buf,1,n,f); fclose(f); FT_Library lib; if(FT_Init_FreeType(&lib))return 3; FT_Face face; FT_Error e=FT_New_Memory_Face(lib,buf,n,-1,&face); if(e){printf("new -1 err %d\n",e);return 0;} long nf=face->num_faces; FT_Done_Face(face); printf("nf %ld\n",nf); for(long idx=0; idx<nf; idx++){ e=FT_New_Memory_Face(lib,buf,n,-(idx+1),&face); if(e){printf("instquery err %d\n",e);continue;} long ni=face->style_flags>>16; printf("face %ld instances %ld flags %lx faceflags %lx glyphs %ld\n",idx,ni,(long)face->style_flags,(long)face->face_flags,(long)face->num_glyphs); FT_Done_Face(face); for(long inst=0; inst<ni+1; inst++){ e=FT_New_Memory_Face(lib,buf,n,(inst<<16)+idx,&face); if(e){printf(" load inst %ld err %d\n",inst,e);continue;} if(FT_HAS_MULTIPLE_MASTERS(face)){ FT_MM_Var* v=NULL; e=FT_Get_MM_Var(face,&v); printf(" mmvar inst%ld err%d v%p\n",inst,e,(void*)v); if(v){printf(" axes%u styles%u\n",v->num_axis,v->num_namedstyles); free(v);} }
 FT_Set_Char_Size(face,20*64,20*64,72,72); for(unsigned gi=0; gi<(unsigned)face->num_glyphs && gi<10; gi++){ e=FT_Load_Glyph(face,gi,FT_LOAD_DEFAULT|FT_LOAD_NO_BITMAP); if(e){} }
 FT_Done_Face(face);} }
 FT_Done_FreeType(lib); free(buf); return 0;}

